import styled from '@emotion/styled';
import { theme } from 'theme';
import { composeStyles } from 'utils/emotion';

const containerShadows = {
  small: '0rem 0.125rem 0.25rem 0rem rgba(0, 0, 0, 0.08)',
  medium: '0rem 0.125rem 0.5rem 0rem rgba(0, 0, 0, 0.08)',
  large: '0rem 0.25rem 1rem 0rem rgba(0, 0, 0, 0.16)',
} as const;

type BasicContainerVariantProps = {
  $border?: 'none' | 'small' | 'gray';
  $borderRadius?: 'none' | 'small' | 'medium' | 'large';
  $shadow?: 'none' | 'small' | 'medium' | 'large';
  $fullWidth?: boolean;
};

export const StyledBasicContainer = styled.div<BasicContainerVariantProps>(
  composeStyles<BasicContainerVariantProps>(
    {
      display: 'flex',
      flexDirection: 'column',
      borderRadius: theme.borderRadius['4'],
      scrollbarColor: 'initial',
    },
    {
      $border: {
        none: {
          border: 'none',
        },
        small: {
          border: '1px solid rgba(20, 20, 20, 0.12)',
        },
        gray: {
          border: '1px solid rgba(20, 20, 20, 0.08)',
        },
      },
      $borderRadius: {
        none: {
          borderRadius: '0',
        },
        small: {
          borderRadius: theme.borderRadius['1'],
        },
        medium: {
          borderRadius: theme.borderRadius['2'],
        },
        large: {
          borderRadius: theme.borderRadius['4'],
        },
      },
      $shadow: {
        none: {
          boxShadow: 'none',
        },
        small: {
          boxShadow: containerShadows.small,
        },
        medium: {
          boxShadow: containerShadows.medium,
        },
        large: {
          boxShadow: containerShadows.large,
        },
      },
      $fullWidth: {
        true: {
          width: '100%',
        },
        false: {},
      },
    },
  ),
);

export const StyledHeaderline = styled.div({
  display: 'flex',
  gap: theme.spacing['1'],
  flexDirection: 'column',
});

export const StyledBasicContainerHeaderContent = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing['2'],
});

export const StyledBasicContainerHeaderColumn = styled.div({
  display: 'flex',
  flexDirection: 'column',
});

export const StyledBasicContainerHeaderRow = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
});

export const StyledBasicContainerTags = styled.div({
  display: 'flex',
  alignItems: 'flex-start',
  gap: '8px',
});
